		return CkCsr_SetExtensionRequest($this->_cPtr,$extensionReqXml);
	}

	/**
	 * Sets a subject distinguished-name attribute identified by oid. For example, OID 2.5.4.9 identifies streetAddress. Use the dedicated properties such as CommonName, Company, and Country for the commonly used subject attributes.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsrRef.html#SetSubjectField
	 * @param ?string $oid
	 * @param ?string $value
	 * @param ?string $asnType
	 * @return bool
	 */
	function SetSubjectField($oid,$value,$asnType) {
		return CkCsr_SetSubjectField($this->_cPtr,$oid,$value,$asnType);
	}

	/**
	 * Verifies the digital signature on the currently loaded CSR using the public key embedded in that request. Returns _TRUE_ when the signature is cryptographically valid; otherwise returns _FALSE_.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkCsrRef.html#VerifyCsr
	 * @return bool
	 */
	function VerifyCsr() {
		return CkCsr_VerifyCsr($this->_cPtr);
	}
}
